package com.farika.soundflow;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.net.*;import java.util.*;
/** Named local QA fixtures and a blocked synthetic HTTP transport, never a real account. */
final class MotionUi {
 static void stage(Instrumentation t,String s)throws Exception{t.runOnMainSync(()->{if(PlaybackService.instance!=null)PlaybackService.instance.pause();});java.io.File ack=new java.io.File(t.getTargetContext().getFilesDir(),"qa_motion_ack");ack.delete();try(java.io.FileOutputStream f=new java.io.FileOutputStream(new java.io.File(t.getTargetContext().getFilesDir(),"qa_motion_stage"))){f.write(s.getBytes("UTF-8"));}Bundle b=new Bundle();b.putString("stage",s);t.sendStatus(7,b);for(int n=0;n<1800&&!ack.exists();n++)Thread.sleep(100);if(!ack.exists())throw new java.io.IOException("Visual QA acknowledgement timeout");}
 static void invoke(Instrumentation t,Object target,String method,Class<?>[] types,Object...args){t.runOnMainSync(()->{try{java.lang.reflect.Method m=target.getClass().getDeclaredMethod(method,types);m.setAccessible(true);m.invoke(target,args);}catch(Exception e){throw new RuntimeException(e);}});}
 static void run(Instrumentation t){Context c=t.getTargetContext();Bundle out=new Bundle();try{
  URL.setURLStreamHandlerFactory(p->p.equals("https")?new URLStreamHandler(){protected URLConnection openConnection(URL u){return new AdvancedCases.Fake(u);}}:null);AdvancedCases.status=403;AdvancedCases.errorJson="{\"error\":\"insufficient_scope\"}";
  c.getSharedPreferences("profile",0).edit().putString("id","123").putString("name","Тестовый аккаунт QA").commit();Session.put(c,"OAuth SYNTHETIC_FIXTURE_NOT_REAL","SYNTHETIC_SESSION_CLIENT_12345");c.getSharedPreferences("appearance",0).edit().putBoolean("motion",true).commit();
  ArrayList<Library.Track> tracks=new ArrayList<>();Library lib=new Library(c);for(int n=0;n<8;n++){Library.Track a=new Library.Track("sc:"+(9000+n),new String[]{"Тихая орбита · QA","Свет в окнах · QA","Вечерний маршрут · QA"}[n%3],"Тестовый исполнитель "+(n+1),120000,false);a.remote=new JSONObject().put("id",""+(9000+n));lib.upsert(a);tracks.add(a);}lib.save();new HomeFeed(c).put(new HomeFeed(c).key("123","mix",true),tracks,"Подборка сохранена · тестовые данные QA",0,0);try(SyncDb db=new SyncDb(c)){db.ensure("123","777","Вечерняя подборка · QA","own");db.snapshot("123","777",tracks);db.state("123","777","9001","BLOCKED","NO_OFFLINE_SOURCE");db.state("123","777","9002","RETRY","IO_ERROR");db.status("123","777","Временные ошибки будут повторены; ограничения доступа не снимаются.");}
  ResumeCases helper=new ResumeCases(t);helper.fixture();Activity a=helper.launch();helper.play();t.runOnMainSync(()->{PlaybackService.instance.repeat=true;PlaybackService.instance.checkpoint();});stage(t,"HOME");invoke(t,a,"openPlayer",new Class<?>[]{});stage(t,"PLAYER");t.runOnMainSync(()->{try{Dialog player=(Dialog)MotionCases.field(a,"playerDialog");if(player!=null&&player.isShowing())player.dismiss();}catch(Exception e){throw new RuntimeException(e);}});
  Activity settings=t.startActivitySync(new Intent(c,AppSettingsActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));stage(t,"SETTINGS");Activity firstDownloads=t.startActivitySync(new Intent(c,AutoDownloadActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));stage(t,"DOWNLOADS");Activity downloads=t.startActivitySync(new Intent(c,AutoDownloadActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));invoke(t,downloads,"details",new Class<?>[]{String.class,String.class,String.class},"123","777","Вечерняя подборка · QA");stage(t,"REASONS");
  t.runOnMainSync(()->{downloads.finish();firstDownloads.finish();settings.finish();});Thread.sleep(1500);invoke(t,a,"accountOperation",new Class<?>[]{String.class,String.class,String.class,String.class},"LIKE","9000","","");Thread.sleep(1200);stage(t,"WRITE403");helper.stop();t.finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("failure",e.toString());t.finish(Activity.RESULT_CANCELED,out);}}
}
